 R=G/f'plans/reviews/six-fish-release-20261104/{s}';inputs=read(R/'release-inputs.json');prior=read(inputs['old_ledger']['path']);assert prior['standard']==standard_snapshot();actual=read(R/'canonical-load.validation.json');cold=read(R/'source-cold-export.validation.json');model=G/f'game/assets/models/fish/{s}.glb';blend=G/f'assets/source/fish/{s}/fish.blend';assert actual['ok']and cold['ok']and actual['model_sha256']==cold['output_sha256']==sha(model)==prior['candidate_files']['model']['sha256'];assert sha(blend)==cold['blend_sha256']==prior['candidate_files']['editable_source']['sha256']
