 data=R/'production-data.json';write(data,{'ok':True,'kind':'user_accepted_same_byte_cyprinid_release','species':s,'bound_inputs':frozen,'installed':True,'user_acceptance':{'date':'2026-11-04','scope':'User explicitly accepted whole six-fish batch as finished assets and requested canonical installation, cleanup and commit+push.'},'static_frozen':True,'original_operator_ledger':inputs['old_ledger'],'immutable_physical_reports':immutable,'retention_map':ref(R/'retention-manifest.json'),'technical_reuse_basis':reuse,'statement':'Original complete490 root/membrane,072,077GPU,head/mouth +/- and actual fin-volume inputs/results retain exact bytes and original scope. Source/model/profile/motion unchanged. New repeat-plan path is not attributed an old plan pass. Normal canonical first/cache/direct,480 controls/360 transition phases and four GPU action pairs newly verified.','fresh_source_export':ref(R/'source-cold-export.validation.json'),'fresh_canonical':ref(R/'canonical-load.validation.json'),'actual_pixels':ref(R/'canonical-pixels.validation.json'),'parameters':ref(R/'parameters.json'),'limits':['Third-party artistic body reference is not a biological measurement or verified specimen.','Subtle low-contrast quilt seams remain within the explicitly accepted appearance.','Discrete490/GPU does not certify all continuous time.','Old report paths are historical, mapping locates retained exact bytes; obsolete experiments are retired.']})
